#!/usr/bin/env python3
"""Pull the drawings the site uses out of Manager's ingredient
file (itself generated from the Copius data). Run after a Copius data change,
giving that file's path:

    python3 tools/extract-art.py <manager repo>/data/ingredients.js
"""
import json, re, sys, pathlib
if len(sys.argv) < 2: sys.exit("usage: extract-art.py <path to Manager's data/ingredients.js>")
SRC = pathlib.Path(sys.argv[1])
IDS = ["porcini","scallop","cod","garlic","chicken","langoustine","fraise-des-bois","cilantro",
       # the home hero draws from these on each visit (js/site.js HERO_POOL)
       "canard-colvert","venison","hare","lamb-shank","american-lobster","dungeness-crab","brown-shrimp",
       "escargot-de-bourgogne","sea-urchin","squid","hake","anchovy","maitake","avocado","corn","kohlrabi",
       "bell-pepper","musquee-de-provence-squash"]
s = SRC.read_text(encoding="utf-8")
rows = json.loads(s.split("=", 1)[1].strip().rstrip(";"))
by = {r["id"]: r for r in rows}
missing = [i for i in IDS if i not in by]
if missing: sys.exit("missing ids: " + ", ".join(missing))
art = {i: {"fr": by[i]["fr"], "en": by[i]["en"], "svg": by[i]["svg"]} for i in IDS}

